/* ===== Unit 2 Prep Journey: lines, slope, and the forms of a linear equation ===== */
/* ---- Coordinate plane widgets ---- */
function planeSVG(o){ const xmin=o.xmin??-10,xmax=o.xmax??10,ymin=o.ymin??-10,ymax=o.ymax??10,W=o.w||300,H=o.h||300,pad=o.pad??22; const X=x=>pad+(x-xmin)/(xmax-xmin)*(W-2*pad), Y=y=>H-pad-(y-ymin)/(ymax-ymin)*(H-2*pad);
  let s=`<svg viewBox="0 0 ${W} ${H}" class="plane ${o.cls||''}" role="img" aria-label="${esc(o.alt||'coordinate plane')}"><rect x="${pad}" y="${pad}" width="${W-2*pad}" height="${H-2*pad}" fill="var(--panel)"/>`;
  const xs=o.xstep||1, ys=o.ystep||1;
  for(let x=Math.ceil(xmin/xs)*xs;x<=xmax;x+=xs) s+=`<line x1="${X(x)}" y1="${pad}" x2="${X(x)}" y2="${H-pad}" stroke="var(--line)" stroke-width="${x===0?2:0.6}" ${x===0?'stroke="var(--ink)"':''}/>`;
  for(let y=Math.ceil(ymin/ys)*ys;y<=ymax;y+=ys) s+=`<line x1="${pad}" y1="${Y(y)}" x2="${W-pad}" y2="${Y(y)}" stroke="var(--line)" stroke-width="${y===0?2:0.6}" ${y===0?'stroke="var(--ink)"':''}/>`;
  const lx=o.labelEvery||(xmax-xmin>12?5:(xmax-xmin>6?2:1)), ly=o.labelEveryY||(ymax-ymin>40?20:(ymax-ymin>12?5:(ymax-ymin>6?2:1)));
  for(let x=Math.ceil(xmin/lx)*lx;x<=xmax;x+=lx) if(x!==0) s+=`<text x="${X(x)}" y="${(ymin<0&&ymax>0?Y(0):H-pad)+12}" font-size="9" text-anchor="middle" fill="var(--muted)" font-family="Nunito,sans-serif" font-weight="800">${x}</text>`;
  for(let y=Math.ceil(ymin/ly)*ly;y<=ymax;y+=ly) if(y!==0) s+=`<text x="${(xmin<0&&xmax>0?X(0):pad)-4}" y="${Y(y)+3}" font-size="9" text-anchor="end" fill="var(--muted)" font-family="Nunito,sans-serif" font-weight="800">${y}</text>`;
  if(o.xlabel) s+=`<text x="${W/2}" y="${H-3}" font-size="9" text-anchor="middle" fill="var(--ink)" font-family="Nunito,sans-serif" font-weight="800">${esc(o.xlabel)}</text>`;
  if(o.ylabel) s+=`<text x="8" y="${H/2}" font-size="9" text-anchor="middle" fill="var(--ink)" font-family="Nunito,sans-serif" font-weight="800" transform="rotate(-90 8 ${H/2})">${esc(o.ylabel)}</text>`;
  (o.lines||[]).forEach(L=>{ let x1,y1,x2,y2; if(L.vertical!==undefined){ x1=x2=L.vertical; y1=ymin; y2=ymax; } else { x1=xmin; x2=xmax; y1=L.m*x1+L.b; y2=L.m*x2+L.b; const clip=(x,y)=>{ if(y<ymin){ return [(ymin-L.b)/L.m, ymin]; } if(y>ymax){ return [(ymax-L.b)/L.m, ymax]; } return [x,y]; }; if(L.m!==0){ [x1,y1]=clip(x1,y1); [x2,y2]=clip(x2,y2); } }
    s+=`<line x1="${X(x1)}" y1="${Y(y1)}" x2="${X(x2)}" y2="${Y(y2)}" stroke="${L.color||'var(--accent)'}" stroke-width="${L.width||3}" ${L.dash?'stroke-dasharray="6 4"':''}/>`; });
  (o.points||[]).forEach(P=>{ s+=`<circle cx="${X(P[0])}" cy="${Y(P[1])}" r="5" fill="${P[2]||'var(--l3)'}" stroke="var(--ink)" stroke-width="2"/>`; if(P[3]) s+=`<text x="${X(P[0])+7}" y="${Y(P[1])-6}" font-size="10" font-weight="800" fill="var(--ink)" font-family="Nunito,sans-serif">${esc(P[3])}</text>`; });
  return s+'</svg>'; }
/* Interactive plane: two draggable points define a line. get() -> {p1,p2}. */
function planeInput(host, opts={}, onChange){
  const xmin=opts.xmin??-10,xmax=opts.xmax??10,ymin=opts.ymin??-10,ymax=opts.ymax??10,W=320,H=320,pad=22; const st={p1:opts.p1||[-3,-2],p2:opts.p2||[2,3]};
  const X=x=>pad+(x-xmin)/(xmax-xmin)*(W-2*pad), Y=y=>H-pad-(y-ymin)/(ymax-ymin)*(H-2*pad); const IX=px=>Math.round(xmin+(px-pad)/(W-2*pad)*(xmax-xmin)), IY=py=>Math.round(ymin+(H-pad-py)/(H-2*pad)*(ymax-ymin));
  host.innerHTML=planeSVG({xmin,xmax,ymin,ymax,w:W,h:H,cls:'planein'})+`<div class="row" style="font-size:.85rem;justify-content:space-between"><span class="muted">Drag the two dots onto the grid; the line runs through both.</span><span class="num readout"></span></div>`;
  const svg=$('svg',host); const g=document.createElementNS('http://www.w3.org/2000/svg','g'); svg.appendChild(g); const ro=$('.readout',host);
  function sync(){ const [x1,y1]=st.p1,[x2,y2]=st.p2; let line=''; if(x1!==x2||y1!==y2){ let ax,ay,bx,by; if(x1===x2){ ax=bx=x1; ay=ymin; by=ymax; } else { const m=(y2-y1)/(x2-x1), b=y1-m*x1; ax=xmin; ay=m*ax+b; bx=xmax; by=m*bx+b; if(m!==0){ const c=(x,y)=>y<ymin?[(ymin-b)/m,ymin]:y>ymax?[(ymax-b)/m,ymax]:[x,y]; [ax,ay]=c(ax,ay); [bx,by]=c(bx,by); } } line=`<line x1="${X(ax)}" y1="${Y(ay)}" x2="${X(bx)}" y2="${Y(by)}" stroke="var(--accent)" stroke-width="3"/>`; }
    g.innerHTML=line+`<circle class="ph" data-p="p1" cx="${X(x1)}" cy="${Y(y1)}" r="11" fill="var(--l3)" stroke="var(--ink)" stroke-width="3" style="cursor:grab"/><circle class="ph" data-p="p2" cx="${X(x2)}" cy="${Y(y2)}" r="11" fill="var(--l5)" stroke="var(--ink)" stroke-width="3" style="cursor:grab"/>`;
    ro.textContent=`(${x1}, ${y1}) and (${x2}, ${y2})`; wire(); }
  let drag=null; const pt=e=>{ const r=svg.getBoundingClientRect(); return [(e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H]; };
  function wire(){ g.querySelectorAll('.ph').forEach(c=>c.addEventListener('pointerdown',e=>{ drag=c.dataset.p; try{ svg.setPointerCapture(e.pointerId);}catch(x){} e.preventDefault(); })); }
  svg.addEventListener('pointermove',e=>{ if(!drag) return; const [px,py]=pt(e); const x=Math.max(xmin,Math.min(xmax,IX(px))), y=Math.max(ymin,Math.min(ymax,IY(py))); if(x!==st[drag][0]||y!==st[drag][1]){ st[drag]=[x,y]; sync(); } });
  const up=()=>{ if(drag){ drag=null; onChange&&onChange(); } }; svg.addEventListener('pointerup',up); svg.addEventListener('pointercancel',up); svg.style.touchAction='none';
  sync(); return {get:()=>({p1:[...st.p1],p2:[...st.p2]}), set:o=>{ if(o.p1) st.p1=o.p1; if(o.p2) st.p2=o.p2; sync(); }};
}
function onLine(eq, x, y){ const t=M.tryParse(eq); if(!t||t.t!=='rel') return false; try{ const a=M.ev(t.parts[0],{x,y}), b=M.ev(t.parts[1],{x,y}); return Math.abs(a-b)<1e-6; }catch(e){ return false; } }
function lineForm(raw){ const c=M.clean(raw).replace(/[\s*]+/g,''); if(/^x=-?[\d./]+$/.test(c)) return 'vert'; if(/^y=[^y=]*$/.test(c)) return 'si'; if(/^[-+]?(\d+(\.\d+)?)?x[-+](\d+(\.\d+)?)?y=-?\d+(\.\d+)?$/.test(c)||/^[-+]?(\d+)?y[-+](\d+)?x=-?\d+$/.test(c)) return 'std'; if(/^y[-+][\d./]+=/.test(c)||/\(x[-+]/.test(c)) return 'ps'; return 'other'; }
const FORM_MSG={si:'That is the right line, but not in slope-intercept form. Write it as y = mx + b.',ps:'Right line. Point-slope form looks like y − y₁ = m(x − x₁).',std:'Right line. Standard form is Ax + By = C with whole-number coefficients and nothing on the right but a number.'};
KIND_EXT.line=(item,raw)=>{ const t=M.tryParse(raw); if(!t||t.t!=='rel'||t.ops.length!==1||t.ops[0]!=='=') return {ok:false,partial:'Write an equation with one equals sign.'}; const canon=M.tryParse(item.answer); if(!canon||!equationEquiv(t,canon)) return {ok:false}; const f=lineForm(raw); const want=item.form||'any'; if(want!=='any'&&f!==want&&!(want==='si'&&f==='vert')) return {ok:false,partial:FORM_MSG[want]}; if(want==='std'&&/[./]/.test(M.clean(raw).replace(/\s/g,''))) return {ok:false,partial:'Standard form uses whole-number coefficients: multiply everything by the denominator.'}; return {ok:true}; };
KIND_EXT.graph=(item,raw,extra)=>{ const g=extra; if(!g) return {ok:false}; const [x1,y1]=g.p1,[x2,y2]=g.p2; if(x1===x2&&y1===y2) return {ok:false,partial:'Your two dots are on the same spot. Pull them apart.'}; const ok1=onLine(item.line,x1,y1), ok2=onLine(item.line,x2,y2); if(!(ok1&&ok2)) return {ok:false}; if(item.needIntercepts){ const pts=[g.p1,g.p2]; const hasX=pts.some(p=>p[1]===0), hasY=pts.some(p=>p[0]===0); if(!(hasX&&hasY)) return {ok:false,partial:'Right line! This one asks you to graph it using the intercepts: put one dot where the line crosses the x-axis and the other where it crosses the y-axis.'}; } return {ok:true}; };
KIND_EXT.table=(item,raw)=>{ const vals=String(raw).split('|'); if(vals.length!==item.ys.length||vals.some(v=>!v.trim())) return {ok:false,partial:'Fill in every box.'}; const bad=vals.map((v,i)=>M.numEq(M.toNumber(v),item.ys[i])?null:item.xs[i]).filter(x=>x!==null); return bad.length?{ok:false,partial:`Recheck x = ${bad.join(', ')}.`}:{ok:true}; };
KIND_EXT.text=(item,raw)=>({ok: item.accept.some(re=>re.test(String(raw).trim()))});
UI_EXT.graph={html:(item,id)=>`<div class="planehost" data-id="${id}"></div>`, wire:(item,el,onChange)=>{ const w=planeInput($('.planehost',el),item.plane||{},onChange); el._get=()=>w.get(); el._plane=w; }, raw:(item,el)=>el._get?JSON.stringify(el._get()):''};
UI_EXT.table={html:(item,id)=>`<div class="tablewrap"><table class="tin"><tr><th>x</th>${item.xs.map(x=>`<td class="num">${x}</td>`).join('')}</tr><tr><th>y</th>${item.xs.map((x,i)=>`<td><input type="text" class="tv" inputmode="decimal" aria-label="y when x is ${x}" style="width:64px;padding:6px"></td>`).join('')}</tr></table></div>`, wire:(item,el,onChange)=>{ el.querySelectorAll('.tv').forEach(i=>i.addEventListener('input',()=>onChange&&onChange())); }, raw:(item,el)=>[...el.querySelectorAll('.tv')].map(i=>i.value).join('|')};
UI_EXT.text={html:(item,id)=>`<input type="text" class="ans" id="${id}" placeholder="${esc(item.placeholder||'')}" autocomplete="off">`, wire:(item,el,onChange)=>{ const i=$('.ans',el); i.addEventListener('input',()=>onChange&&onChange()); i.addEventListener('keydown',e=>{ if(e.key==='Enter'){ e.preventDefault(); const b=$('.check',el); b&&b.click(); } }); }, raw:(item,el)=>($('.ans',el)||{}).value||''};
/* Tile patterns */
function tileSVG(kind,n){ const u=14; let cells=[]; if(kind==='T'){ for(let i=0;i<3;i++) cells.push([i,0,'#c9ced6']); for(let j=1;j<=n;j++) cells.push([1,j,'#333']); } else { for(let j=0;j<n;j++){ cells.push([0,j,'#333']); cells.push([2,j,'#333']); } cells.push([1,n,'#333']); cells.push([0,n,'#333']); cells.push([2,n,'#333']); } const w=3*u+4, h=(n+2)*u+4; return `<svg viewBox="0 0 ${w} ${h}" width="${w*1.2}" height="${h*1.2}" aria-hidden="true">${cells.map(([x,y,c])=>`<rect x="${x*u+2}" y="${(kind==='T'?y:(n-y))*u+2}" width="${u-1}" height="${u-1}" fill="${c}" stroke="#1d2733" stroke-width="1"/>`).join('')}</svg>`; }
const tilesHTML=(kind,count)=>`<div class="row" style="gap:18px;align-items:flex-end;margin:8px 0">${Array.from({length:3},(_,i)=>`<div style="text-align:center"><div class="muted" style="font-size:.75rem">${kind==='T'?'Figure':'Stage'} ${i+1}</div>${tileSVG(kind,count(i+1))}</div>`).join('')}</div>`;
/* Four-graph matcher option */
const miniGraph=(m,b,o={})=>planeSVG({xmin:0,xmax:o.xmax||5,ymin:0,ymax:o.ymax||16,w:170,h:150,pad:20,lines:[{m,b}],xlabel:o.xlabel,ylabel:o.ylabel,labelEvery:1,labelEveryY:o.ly||4});

