  mk({id:'q9',p:3,skill:'slope',learn:1,kind:'num',work:true,prompt:`<b>9.</b> Slope through (${p1[0]}, ${p1[1]}) and (${p2[0]}, ${p2[1]}).`,answer:frs(m9n,m9d),show:'m = '+frs(m9n,m9d),variants:[{num:m9n!==0?m9d/m9n:99,why:'Run over rise; slope is rise over run.'}],diag:'(y₂ − y₁)/(x₂ − x₁), same order top and bottom.'});
  const vx=ri(-6,6); mk({id:'q10',p:3,skill:'slope',learn:1,kind:'text',accept:[/undefined/i,/^no slope$/i,/does not exist/i,/^dne$/i],work:true,prompt:`<b>10.</b> Slope through (${vx}, ${ri(-6,2)}) and (${vx}, ${ri(3,8)}). (Type a number, or the word for a slope that does not exist.)`,show:'undefined',diag:'Same x: run is 0, slope undefined (vertical).'});
  let fa,fb; for(;;){ fa=pick([[1,2,1,4],[1,3,1,6],[3,4,1,4]]); fb=pick([[1,4,3,4],[2,3,1,3],[1,2,1,2]]); if(fa[0]/fa[1]!==fb[0]/fb[1]) break; } // points (fa0/fa1, fa2/fa3) and (fb0/fb1, fb2/fb3)
  const rise=fb[2]/fb[3]-fa[2]/fa[3], run=fb[0]/fb[1]-fa[0]/fa[1]; const m11=rise/run; const m11f=(()=>{ for(let d=1;d<=24;d++){ if(Math.abs(m11*d-Math.round(m11*d))<1e-9) return frs(Math.round(m11*d),d); } return String(m11); })();
  mk({id:'q11',p:3,skill:'slope',learn:1,kind:'num',work:true,prompt:`<b>11.</b> Slope through (${fr(fa[0],fa[1])}, ${fr(fa[2],fa[3])}) and (${fr(fb[0],fb[1])}, ${fr(fb[2],fb[3])}).`,answer:m11f,show:'m = '+m11f,diag:'Subtract the fractions with common denominators, then divide.'});
  const hy=ri(-6,6); mk({id:'q12',p:3,skill:'slope',learn:1,kind:'num',work:true,prompt:`<b>12.</b> Slope through (${ri(-6,0)}, ${hy}) and (${ri(1,6)}, ${hy}).`,answer:'0',show:'m = 0',diag:'Same y: rise is 0, slope 0 (horizontal).'});
  const sm=pick([2,3,4,-2,-3]), xa=ri(3,8), xb=ri(-3,2), yb=ri(-6,6); const wv=yb+sm*(xa-xb); mk({id:'q13',p:3,skill:'slope',learn:1,kind:'num',work:true,prompt:`<b>13.</b> What is w if the line through (${xa}, w) and (${xb}, ${yb}) has slope ${sm}?`,answer:String(wv),show:'w = '+wv,diag:`(w − ${yb})/(${xa} − ${xb}) = ${sm}.`});
  mk({id:'q14',p:3,skill:'slope',learn:1,kind:'line',form:'si',work:true,prompt:U2_ITEMS.find(i=>i.id==='q14').prompt,answer:'y=(m/t)*x',show:'y = (m/t)x',diag:'Slope m/t, through the origin.'});
  // slope-intercept 15–21
